"""Maximum output volume: 6 cases x 64 audit/step events, biggest state."""
import json
import random
import sys

sys.path.insert(0, '/workspace/submission')


def build(seed=0):
    rng = random.Random(seed)
    nodes = 32
    edges = []
    pairs = [(u, v) for u in range(nodes) for v in range(nodes) if u != v]
    rng.shuffle(pairs)
    for u, v in pairs[:64]:
        edges.append([u, v, rng.choice([1, 5, 100, 1000])])
    adj = {}
    for i, e in enumerate(edges):
        adj.setdefault(e[0], []).append(i)

    def walk(s, t):
        for _ in range(50):
            path, cur, seen = [], s, {s}
            while len(path) < 12:
                outs = [i for i in adj.get(cur, []) if edges[i][1] not in seen]
                if not outs:
                    break
                i = rng.choice(outs)
                path.append(i); seen.add(edges[i][1]); cur = edges[i][1]
                if cur == t:
                    return path
            if path and cur == t:
                return path
        return None
    coms = []
    for k in range(24):
        s = rng.randrange(nodes); t = rng.randrange(nodes)
        while t == s:
            t = rng.randrange(nodes)
        paths, guard = [], 0
        while len(paths) < 4 and guard < 60:
            guard += 1
            w = walk(s, t)
            if w is None:
                continue
            if any(p is not None and tuple(p) == tuple(w) for p in paths):
                continue
            paths.append(w)
        coms.append({'source': s, 'sink': t, 'demand': rng.choice([0, 1, 100]), 'paths': paths})
    ids = list(range(24))
    rng.shuffle(ids)
    workers = [sorted(ids[i * 3:(i + 1) * 3]) for i in range(8)]
    events = []
    tickets = []
    for i in range(64):
        r = rng.random()
        if r < 0.12 and len(tickets) < 6:
            events.append({'op': 'issue', 'id': rng.randrange(10**9), 'worker': rng.randrange(8)})
            tickets.append(events[-1]['id'])
        elif r < 0.25 and tickets:
            events.append({'op': 'deliver', 'id': rng.choice(tickets)})
        elif r < 0.45:
            events.append({'op': 'step'})
        elif r < 0.5:
            events.append({'op': 'retune', 'rho': rng.randint(1, 8)})
        else:
            events.append({'op': 'audit'})
    a = rng.randint(1, 16); b = rng.randint(a // 2 + 1, a)
    return {'nodes': nodes, 'edges': edges, 'commodities': coms, 'workers': workers,
            'quorum': rng.randint(1, 8), 'max_lag': rng.randint(0, 3),
            'relax': [a, b], 'rho': rng.randint(1, 8),
            'mode': rng.choice(['route', 'admit']), 'events': events}


if __name__ == '__main__':
    cases = [build(s) for s in range(6)]
    sys.stdout.write(json.dumps({'cases': cases}, separators=(',', ':')))
